import { test, expect } from '@grafana/plugin-e2e';

// E2E for the Spectrogram panel plugin.
//
// Runs against the provisioned dev dashboard (provisioning/dashboards/
// dashboard.json, generated by tools/gen_dashboard.py):
//   3. "$band" -> Postgres record-format query, repeated per band. Needs PSD
//      records loaded for the last 24 h (see db/README.md).
//   1. dev: no data + "Demo data when empty" -> synthetic data + badge.
//
// No screenshot-based assertions; tools/verify_dashboard.mjs does the
// deeper pixel-level checks.

test.describe('Spectrogram panel', () => {
  test('renders a spectrogram canvas and shows the synthetic badge when there is no data', async ({
    gotoPanelEditPage,
    readProvisionedDashboard,
  }) => {
    const dashboard = await readProvisionedDashboard({ fileName: 'dashboard.json' });
    const panelEditPage = await gotoPanelEditPage({ dashboard, id: '1' });
    await expect(panelEditPage.panel.locator).toBeVisible();
    await expect(panelEditPage.panel.locator.getByTestId('spectrogram-canvas')).toBeVisible();
    // Panel 1 has no data and demoWhenEmpty on, so it shows synthetic data.
    await expect(panelEditPage.panel.locator.getByText('synthetic data', { exact: true })).toBeVisible();
  });

  test('renders real data from record-format Postgres band records', async ({
    gotoPanelEditPage,
    readProvisionedDashboard,
  }) => {
    const dashboard = await readProvisionedDashboard({ fileName: 'dashboard.json' });
    const panelEditPage = await gotoPanelEditPage({ dashboard, id: '3' });
    await expect(panelEditPage.panel.locator).toBeVisible();
    await expect(panelEditPage.panel.locator.getByTestId('spectrogram-canvas')).toBeVisible();
    await expect(panelEditPage.panel.locator.getByText('synthetic data', { exact: true })).toHaveCount(0);
    await expect(panelEditPage.panel.locator.getByText('No PSD data in this time range')).toHaveCount(0);
  });

  test('exposes the spectrogram options in the panel options pane', async ({
    gotoPanelEditPage,
    readProvisionedDashboard,
  }) => {
    const dashboard = await readProvisionedDashboard({ fileName: 'dashboard.json' });
    const panelEditPage = await gotoPanelEditPage({ dashboard, id: '1' });
    // Grafana 13.x groups the plugin's setPanelOptions under a group named
    // after the panel ("RF Spectrogram"), not the generic "Panel options" group.
    const options = panelEditPage.getCustomOptions('RF Spectrogram');
    // Wait for the options pane to hydrate before asserting on individual fields.
    for (const name of ['Record field', 'Frequency field', 'Value field', 'Color min', 'Color max']) {
      await expect(options.getTextInput(name)).toBeVisible();
    }
    for (const name of ['Normalize', 'Pixel aggregation', 'Time axis', 'Colormap']) {
      await expect(options.getRadioGroup(name).element).toBeVisible();
    }
    for (const name of ['Show axes', 'Show legend', 'Demo data when empty']) {
      await expect(options.getSwitch(name).element).toBeVisible();
    }
  });
});
